import logging


class Cell(object):
    """Cell class"""

    def __init__(self, alias, used_attenuator, rf_paths):
        self.alias = alias
        self.used_attenuator = used_attenuator
        self.cell_config_list = rf_paths
        logging.debug('New cell {} created with RF paths: {} on attenuator {}.'.format(alias, rf_paths, used_attenuator))

    def connect_to_attenuator(self, att_pool):
        """Establish connection of attenuators related to this cell"""
        for att_name in self.used_attenuator:
            for rf_path_details in self.cell_config_list:
                att = att_pool.get_attenuator(att_name)
                att.connect_attenuator_controller(rf_paths_at_attenuator=rf_path_details['rf_paths_at_attenuator'])
            self._reserve_rf_paths_at_attenuator(att_name, att)

    def set_attenuation(self, att_pool, attenuation_value):
        """Set attenuation on all rf paths related to the cell"""
        for att_name in self.used_attenuator:
            for rf_path_details in self.cell_config_list:
                self._set_rf_paths_attenuation(att_name, rf_path_details, attenuation_value, att_pool)

    def read_attenuation(self, att_pool):
        """Read attenuation from first rf path related to the cell"""
        for att_name in self.used_attenuator:
            for rf_path_details in self.cell_config_list:
                return self._read_rf_path_attenuation(att_name, rf_path_details, att_pool)

    def _set_rf_paths_attenuation(self, att_name, rf_paths_details, attenuation_value, att_pool):
        if rf_paths_details['used_attenuator'] == att_name:
            att = att_pool.get_attenuator(att_name)
            rf_paths = rf_paths_details['rf_paths_at_attenuator']
            att.set_rf_paths_attenuation(rf_paths, attenuation_value)

    def _read_rf_path_attenuation(self, att_name, rf_paths_details, att_pool):
        if rf_paths_details['used_attenuator'] == att_name:
            att = att_pool.get_attenuator(att_name)
            rf_paths = rf_paths_details['rf_paths_at_attenuator']
            return att.read_rf_paths_attenuation(rf_paths)
        return None

    def _reserve_rf_paths_at_attenuator(self, att_name, att):
        for rf_path_details in self.cell_config_list:
            if rf_path_details['used_attenuator'] == att_name:
                rf_paths = rf_path_details['rf_paths_at_attenuator']
                for rf_path in rf_paths:
                    att.reserve_port(rf_path)
                    logging.debug('Reserving port {} on attenuator {}'.format(rf_path, att_name))

    def disconnect_from_attenuator(self, att_pool):
        """Release connections from attenuator related to this cell"""
        for rf_path_details in self.cell_config_list:
            rf_paths = rf_path_details['rf_paths_at_attenuator']
            att_name = rf_path_details['used_attenuator']
            att = att_pool.get_attenuator(att_name)
            att.disconnect_attenuator_controller(rf_paths_at_attenuator=rf_paths)
            self._release_rf_paths(att, att_name, rf_paths)

    def _release_rf_paths(self, att, att_name, rf_paths):
        for rf_path in rf_paths:
            att.release_port(rf_path)
            logging.debug('Releasing port {} on attenuator {}'.format(rf_path, att_name))
